style.css:
@-moz-document domain("youtube.com") {
/* Fondo general */
body, ytd-app, #page-manager, ytd-masthead, ytd-watch-flexy {
  background-color: #fce4ec !important;
  color: #4a4a4a !important;
}

/* Panel lateral y secciones */
ytd-guide-section-renderer, tp-yt-app-drawer, ytd-mini-guide-renderer {
  background-color: #f8bbd0 !important;
  color: #4a4a4a !important;
}

/* Tarjetas de video */
ytd-rich-item-renderer, ytd-video-renderer, ytd-grid-video-renderer, ytd-compact-video-renderer {
  background-color: #fce4ec !important;
  border-radius: 12px !important;
  padding: 8px !important;
}

/* Títulos y descripciones */
#video-title, .title, .yt-simple-endpoint, .style-scope {
  color: #4a4a4a !important;
}

/* Botones */
ytd-toggle-button-renderer, ytd-button-renderer, paper-button, button {
  background-color: #f8bbd0 !important;
  color: #4a4a4a !important;
  border-radius: 8px !important;
}

/* Barra de búsqueda */
#search-input, #search-form {
  background-color: #fce4ec !important;
  color: #4a4a4a !important;
  border: 1px solid #f48fb1 !important;
}

/* Footer y otros paneles */
ytd-metadata-row-renderer, ytd-comments-header-renderer, ytd-comment-thread-renderer {
  background-color: #fce4ec !important;
  color: #4a4a4a !important;
}

/* Scrollbar */
::-webkit-scrollbar {
  width: 10px;
}
::-webkit-scrollbar-track {
  background: #fce4ec;
}
::-webkit-scrollbar-thumb {
  background-color: #f48fb1;
  border-radius: 10px;
}

/* Evita texto blanco sobre rosado */
* {
  color: #4a4a4a !important;
}

/* Corrige fondo de menús desplegables */
tp-yt-paper-listbox, tp-yt-paper-dialog {
  background-color: #f8bbd0 !important;
}

/* Iconos */
yt-icon, svg {
  fill: #4a4a4a !important;
}

/* Encabezado (barra superior) */
ytd-masthead {
  background-color: #f8bbd0 !important;
}

/* Modo cine y fondo de video */
ytd-watch-flexy[theater] #player-theater-container, #player-container {
  background-color: #f8bbd0 !important;
}
}
